function stripQuotedEmailHistory(text) {
  if (!text) return "";
  let t2 = String(text).replace(/\r\n/g, "\n");
  t2 = t2.replace(/\n?On\s[\s\S]{0,300}?\swrote:[\s\S]*$/i, "");
  t2 = t2.replace(/\n?-{2,}\s*(Original Message|Forwarded message)[\s\S]*$/i, "");
  t2 = t2.replace(/\n?_{5,}[\s\S]*$/, "");
  t2 = t2.replace(/\n?From:\s.*\n(?:Sent|Date|To|Subject):[\s\S]*$/i, "");
  t2 = t2.replace(/^>.*$/gm, "");
  t2 = t2.replace(/\n--\s*\n[\s\S]*$/, "");
  t2 = t2.replace(/\n\s*(Regards|Best regards|Kind regards|Thanks|Thank you|Warm regards|Sincerely|Cheers),?\s*\n[\s\S]*$/i, "");
  return t2.trim();
}
